/* ===== src/tokens.css ===== */
/* 烟水渡 v5 | Author: @jiuyi0204 | 视觉令牌与固定素材 */
@font-face {
    font-family: "Zhuque Fangsong";
    src: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/2b1972108f9dc4082438d5f0fbeebe81d1d4b1ef/font-library/v2/fonts/zhuquefangsong/zhuquefangsong.woff2") format("woff2");
    font-display: swap;
    font-style: normal;
    font-weight: 400;
}

@font-face {
    font-family: "Ma Shan Zheng";
    src: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/4eff68933698e82715fcc4450c74b039c9988f19/font-library/v1/fonts/mashanzheng/mashanzheng.woff2") format("woff2");
    font-display: swap;
    font-style: normal;
    font-weight: 400;
}

:root {
    --ysd-paper: #f6ecd9;
    --ysd-paper-page: #efe0c5;
    --ysd-paper-raised: #fff9ed;
    --ysd-paper-control: #f8ecd7;
    --ysd-paper-hover: #ead2aa;
    --ysd-paper-disabled: #e4d6bc;
    --ysd-paper-veil: rgba(66, 55, 38, 0.22);
    --ysd-popup-blur: 0px;
    --ysd-ink: #241a13;
    --ysd-ink-soft: #654a38;
    --ysd-ink-muted: #776a5d;
    --ysd-ink-faint: rgba(67, 42, 26, 0.18);
    --ysd-cinnabar: #ad2f27;
    --ysd-cinnabar-dark: #771b17;
    --ysd-jade: #3f6858;
    --ysd-jade-soft: #d6e0d6;
    --ysd-blush: #d88fa5;
    --ysd-blush-soft: #f0cbd3;
    --ysd-mist-blue: #657786;
    --ysd-mist-blue-soft: #dce3e6;
    --ysd-bronze: #936436;
    --ysd-warning: #9c5627;
    --ysd-error: #902c28;
    --ysd-success: #496d55;
    --ysd-info: #4e6f77;
    --ysd-hairline: rgba(87, 55, 31, 0.32);
    --ysd-focus-ring: rgba(173, 47, 39, 0.18);
    --ysd-shadow: 0 10px 28px rgba(61, 39, 23, 0.14);
    --ysd-radius-sm: 3px;
    --ysd-radius-md: 8px;
    --ysd-radius-lg: 14px;
    --ysd-gap-xs: 0.28rem;
    --ysd-gap-sm: 0.55rem;
    --ysd-gap-md: 0.9rem;
    --ysd-gap-lg: 1.45rem;
    --ysd-speed: 160ms;
    --ysd-font-body: "Zhuque Fangsong", "Songti SC", "Noto Serif CJK SC", "SimSun", serif;
    --ysd-font-display: "Ma Shan Zheng", "STKaiti", "KaiTi", cursive;
    --ysd-paper-texture: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/30bedec54b0fcef7cf9e8ec3f98a12048d8e7762/assets/%E7%83%9F%E6%B0%B4%E6%B8%A1/xuan-paper-texture.png");
    --ysd-ui-sprite: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/3ccef8eae14e6c0f8e37c1f408ce62fbbc8e3505/assets/%E7%83%9F%E6%B0%B4%E6%B8%A1/ancient-ui-sprite.png");
    --ysd-avatar-frame: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/3ccef8eae14e6c0f8e37c1f408ce62fbbc8e3505/assets/%E7%83%9F%E6%B0%B4%E6%B8%A1/ancient-avatar-frame.png");
    --ysd-selection-motifs: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/4625f4df55bfcd08a66428124825a7b412605383/assets/%E7%83%9F%E6%B0%B4%E6%B8%A1/v5/selection-motifs.png");
    --ysd-branch-dividers: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/4625f4df55bfcd08a66428124825a7b412605383/assets/%E7%83%9F%E6%B0%B4%E6%B8%A1/v5/peach-willow-dividers.png");
    --ysd-select-marker: url("data:image/svg+xml,%3Csvg%20xmlns=%27http://www.w3.org/2000/svg%27%20viewBox=%270%200%2024%2024%27%3E%3Cpath%20d=%27M5%208c5%200%209%203%2011%208M7%207c4-1%207%200%209%203-4%201-7%200-9-3Z%27%20fill=%27none%27%20stroke=%27%233f6858%27%20stroke-width=%271.8%27%20stroke-linecap=%27round%27/%3E%3Ccircle%20cx=%2717%27%20cy=%2716%27%20r=%272%27%20fill=%27%23ad2f27%27/%3E%3C/svg%3E");
    --ysd-control-transparent: transparent;
    --ysd-selection-background-size: 400% 200%;
    --ysd-selection-off-position: 33.333% 0%;
    --ysd-selection-on-position: 0% 0%;
    --ysd-radio-off-position: 100% 0%;
    --ysd-radio-on-position: 66.666% 0%;
    --ysd-motif-lotus-position: 0% 100%;
    --ysd-motif-branch-position: 33.333% 100%;
    --ysd-motif-butterfly-position: 66.666% 100%;
    --ysd-motif-mountain-position: 100% 100%;
    --ysd-ui-falling-leaves-position: 33.333% 100%;
    --ysd-ui-bamboo-position: 100% 100%;
    --ysd-prompt-action-size: 1.34rem;
    --ysd-prompt-type-size: 1.08rem;
    --ysd-icon-image-content: " ";
    --ysd-world-entry-on-label: "启";
    --ysd-world-entry-off-label: "止";
    --ysd-world-entry-drag-label: "序";
    --ysd-editor-expand-label: "展";
    --ysd-close-label: "收";
    --ysd-media-enlarge-label: "赏";
    --ysd-media-caption-label: "题";
    --ysd-media-delete-label: "删";
    --ysd-media-open-label: "阅";
    --ysd-media-file-label: "卷";
    --ysd-media-prev-label: "前";
    --ysd-media-next-label: "后";
    --ysd-media-play-label: "奏";
    --ysd-media-pause-label: "止";
    --ysd-media-sound-label: "声";
    --ysd-media-mute-label: "静";
    --ysd-media-controls-hidden-opacity: 0;
    --ysd-media-controls-visible-opacity: 1;
    --ysd-excluded-tag-marker: "❀";
    --ysd-selection-clip: none;
    --ysd-control-disabled-opacity: 0.48;
    --ysd-branch-opacity: 0.82;
    --ysd-prompt-hover-surface: rgba(234, 210, 170, 0.34);
    --ysd-prompt-focus-surface: rgba(214, 224, 214, 0.42);
    --ysd-checkbox-indicator-content: "";
    --ysd-checkbox-indicator-size: 1.42rem;
    --ysd-checkbox-indicator-clip: none;
    --ysd-checkbox-indicator-off-transform: scale(0.72);
    --ysd-checkbox-indicator-on-transform: scale(0.94);
    --ysd-avatar-frame-outset: -0.42rem;
    --ysd-range-track: var(--ysd-branch-dividers);
    --ysd-range-track-disabled: var(--ysd-branch-dividers);
    --ysd-range-track-size: 100% 200%;
    --ysd-range-track-position: center bottom;
    --ysd-range-track-height: 0.72rem;
    --ysd-range-track-opacity: 0.84;
    --ysd-range-track-disabled-opacity: 0.42;
    --ysd-range-host-background-image: none;
    --ysd-range-thumb-size: 1.42rem;
    --ysd-toast-icon-position: absolute;
    --ysd-toast-icon-inline-start: 0.78rem;
    --ysd-toast-icon-top: 50%;
    --ysd-toast-icon-size: 1.72rem;
    --ysd-toast-icon-transform: translateY(-50%);
    --ysd-icon-repeat: no-repeat;
    --ysd-decoration-pointer-events: none;
    --ysd-semantic-icon-display: inline-block;
    --ysd-semantic-icon-size: 1.18em;
    --ysd-loading-motif-size: 1.42em;
    --ysd-semantic-icon-font-size: 0;
    --ysd-semantic-icon-line-height: 1;
    --ysd-semantic-icon-align: -0.18em;
    --ysd-window-action-size: 1.38rem;
    --ysd-action-create-position: 66.666% 33.333%;
    --ysd-action-import-position: 33.333% 100%;
    --ysd-action-export-position: 100% 66.666%;
    --ysd-action-edit-position: 100% 100%;
    --ysd-action-delete-position: 0% 100%;
    --ysd-action-save-position: 0% 33.333%;
    --ysd-action-copy-position: 100% 33.333%;
    --ysd-action-refresh-position: 33.333% 66.666%;
    --ysd-action-lore-position: 100% 0%;
    --ysd-action-search-position: 66.666% 66.666%;
    --ysd-action-group-position: 66.666% 33.333%;
    --ysd-action-grid-position: 33.333% 33.333%;

    /* v7 状态合同别名：所有灰色与交互状态只能回指这些批准令牌。 */
    --theme-surface: var(--ysd-paper-raised);
    --theme-surface-muted: var(--ysd-paper-control);
    --theme-surface-disabled: var(--ysd-paper-disabled);
    --theme-text-primary: var(--ysd-ink);
    --theme-text-secondary: var(--ysd-ink-soft);
    --theme-text-disabled: var(--ysd-ink-muted);
    --theme-border: var(--ysd-hairline);
    --theme-focus-ring: rgba(63, 104, 88, 0.16);
    --theme-opacity-disabled: 1;
    --theme-shadow: var(--ysd-shadow);
    --theme-code-inline-surface: rgba(157, 51, 42, 0.07);
    --theme-code-block-surface: #f0dfc3;
    --theme-code-text: var(--ysd-ink);
    --theme-code-muted: var(--ysd-ink-muted);
    --theme-code-accent: var(--ysd-jade);
    --theme-code-selection: #d6e0d6;
    --theme-overflow-auto: auto;
}

/* ===== src/kernel/base.css ===== */
/* 功能保护与全局基础：纹理只用于页面级外壳，不改变官方抽屉骨架。 */
body {
    color: var(--ysd-ink);
    background-color: #d7c6ab;
    background-image:
        linear-gradient(rgba(239, 228, 207, 0.9), rgba(239, 228, 207, 0.9)),
        var(--ysd-paper-texture);
    font-family: var(--ysd-font-body);
}

#sheld,
.drawer-content,
.popup,
.modal,
.toast {
    color: var(--ysd-ink);
    font-family: var(--ysd-font-body);
}

:where(#sheld, .drawer-content, .popup, .modal, #options, #completion_prompt_manager_popup)
    :is(button, [role="button"], a, input, textarea, select, .menu_button, .drawer-icon, .interactable):focus-visible {
    outline: 2px solid var(--ysd-cinnabar);
    outline-offset: 2px;
    box-shadow: 0 0 0 4px var(--ysd-focus-ring);
}

:where(#sheld, .drawer-content, .popup, .modal, #options)
    :is(input, textarea, select, .text_pole) {
    color: var(--ysd-ink);
    border: 1px solid var(--ysd-hairline);
    border-radius: var(--ysd-radius-sm);
    background: var(--ysd-paper-raised);
    box-shadow: inset 0 1px 4px rgba(76, 58, 39, 0.06);
    font-family: var(--ysd-font-body);
    text-shadow: none;
}

:where(#sheld, .drawer-content, .popup, .modal, #options)
    :is(input, textarea, select, .text_pole):disabled {
    color: var(--ysd-ink-muted);
    opacity: 1;
    background: var(--ysd-paper-disabled);
    text-shadow: none;
    filter: none;
}

:where(.drawer-content, .popup, .modal, #options)
    :is(.menu_button, button, [role="button"]) {
    color: var(--ysd-ink);
    border-color: var(--ysd-hairline);
    border-radius: var(--ysd-radius-sm);
    background: var(--ysd-paper-control);
    box-shadow: none;
    text-shadow: none;
    filter: none;
    opacity: 1;
    transition: color var(--ysd-speed), background-color var(--ysd-speed), transform var(--ysd-speed);
}

:where(.drawer-content, .popup, .modal, #options)
    :is(.menu_button, button, [role="button"]):hover {
    color: var(--ysd-cinnabar-dark);
    background: var(--ysd-paper-hover);
}

:where(.drawer-content, .popup, .modal) input[type="checkbox"],
:where(.drawer-content, .popup, .modal) input[type="radio"],
:where(.drawer-content, .popup, .modal) input[type="range"] {
    accent-color: var(--ysd-cinnabar);
}

/* ===== src/kernel/scrollbars.css ===== */
/* 只隐藏滚动条外观；不改变 overflow、触摸、指针、键盘或滑杆功能。 */
:where(
    html,
    body,
    #sheld,
    #sheld *,
    #chat,
    .drawer-content,
    .popup-content,
    .scrollable,
    .select2-results__options,
    #send_textarea,
    #chat .mes_text pre,
    #chat .mes_text .table-responsive
) {
    scrollbar-width: none;
    -ms-overflow-style: none;
}

:where(
    html,
    body,
    #sheld,
    #sheld *,
    #chat,
    .drawer-content,
    .popup-content,
    .scrollable,
    .select2-results__options,
    #send_textarea,
    #chat .mes_text pre,
    #chat .mes_text .table-responsive
)::-webkit-scrollbar {
    width: 0;
    height: 0;
}

#top-settings-holder {
    scrollbar-width: none;
    -ms-overflow-style: none;
}

#top-settings-holder::-webkit-scrollbar {
    width: 0;
    height: 0;
}

/* ===== src/windows/visual-states.css ===== */
/* v7 visual-state registry: explicit real-node state matrix. */

#chat .mes_reasoning_details {
    color: var(--theme-text-primary);
    background: var(--theme-surface);
    border: 1px solid var(--theme-border);
    opacity: 1;
    filter: none;
    box-shadow: none;
    text-shadow: none;
}

#chat .mes_reasoning_details:not([open]) {
    color: var(--theme-text-primary);
    background: var(--theme-surface);
    border: 1px solid var(--theme-border);
    opacity: 1;
    filter: none;
    box-shadow: none;
    text-shadow: none;
}

#chat .mes_reasoning_details[open] {
    color: var(--theme-text-primary);
    background: var(--theme-surface-muted);
    border: 1px solid var(--theme-border);
    opacity: 1;
    filter: none;
    box-shadow: none;
    text-shadow: none;
}

#chat .mes_reasoning_details[data-state="thinking"] {
    color: var(--theme-text-primary);
    background: var(--theme-surface);
    border: 1px solid var(--theme-border);
    opacity: 1;
    filter: none;
    box-shadow: none;
    text-shadow: none;
}

#chat .mes_reasoning_details[data-state="complete"] {
    color: var(--theme-text-primary);
    background: var(--theme-surface);
    border: 1px solid var(--theme-border);
    opacity: 1;
    filter: none;
    box-shadow: none;
    text-shadow: none;
}

#chat .mes_reasoning_details:focus-within {
    color: var(--theme-text-primary);
    background: var(--theme-surface);
    border: 1px solid var(--theme-border);
    opacity: 1;
    filter: none;
    box-shadow: none;
    text-shadow: none;
    outline: 2px solid var(--theme-focus-ring);
}

#chat .mes_reasoning_details .mes_reasoning {
    color: var(--theme-text-primary);
    background: transparent;
    border: none;
    opacity: 1;
    filter: none;
    box-shadow: none;
    text-shadow: none;
}

#chat .mes_reasoning_details .mes_reasoning_arrow {
    color: var(--theme-text-secondary);
