/* ===== src/chat-layout.css ===== */
/* 主聊天 v4：User 左题签右动态头像；Character 无头像整宽长卷。 */
#sheld {
    border: 1px solid var(--ysd-hairline);
    border-radius: var(--ysd-radius-lg);
    background-color: var(--ysd-paper-page);
    box-shadow: var(--ysd-shadow);
}

#chat {
    color: var(--ysd-ink);
    background:
        linear-gradient(rgba(255, 250, 240, 0.91), rgba(246, 234, 212, 0.91)),
        var(--ysd-paper-texture),
        var(--ysd-paper);
}

#chat .mes {
    position: relative;
    display: grid;
    grid-template-columns: minmax(0, 1fr);
    align-items: start;
    width: 100%;
    padding: clamp(0.9rem, 1.8vw, 1.45rem) clamp(0.8rem, 3.1vw, 2.5rem);
    overflow: visible;
    border: 0;
    border-bottom: 0;
    border-radius: 0;
    background: transparent;
    box-shadow: none;
}

#chat .mes .mes_block {
    width: 100%;
    min-width: 0;
    padding: 0;
    overflow: visible;
}

#chat .mes[is_user="true"] {
    grid-template-columns: minmax(0, 1fr) minmax(12rem, 28%);
    column-gap: clamp(1rem, 3vw, 2.2rem);
    align-items: center;
    min-height: clamp(7.5rem, 11vw, 10rem);
    padding-block: clamp(1rem, 2.2vw, 1.85rem);
}

#chat .mes[is_user="true"] .mes_block {
    grid-column: 1;
    grid-row: 1;
    align-self: center;
    padding: clamp(0.35rem, 1.3vw, 0.9rem) 0 clamp(0.35rem, 1.3vw, 0.9rem) clamp(0.2rem, 1.2vw, 0.9rem);
}

#chat .mes[is_user="true"] .mesAvatarWrapper {
    grid-column: 2;
    grid-row: 1;
    display: grid;
    grid-template-columns: 1fr auto auto auto;
    align-items: end;
    gap: var(--ysd-gap-sm);
    width: 100%;
    min-width: 0;
    margin: 0;
}

#chat .mes[is_user="true"] .mesAvatarWrapper .avatar {
    grid-column: 1 / -1;
    grid-row: 1;
    width: 100%;
    height: clamp(7.5rem, 11vw, 10rem);
    margin: 0;
    overflow: hidden;
    border: 0;
    border-radius: 0;
    background: transparent;
    box-shadow: none;
}

#chat .mes[is_user="true"] .mesAvatarWrapper .avatar img {
    display: block;
    width: 100%;
    height: 100%;
    margin: 0;
    object-fit: cover;
    object-position: 50% 38%;
    border: 0;
    border-radius: 0;
    opacity: 1;
    image-rendering: auto;
    filter: none;
    -webkit-mask-image: linear-gradient(90deg, transparent 0%, rgba(0, 0, 0, 0.76) 15%, #000 31%, #000 69%, rgba(0, 0, 0, 0.76) 85%, transparent 100%);
    mask-image: linear-gradient(90deg, transparent 0%, rgba(0, 0, 0, 0.76) 15%, #000 31%, #000 69%, rgba(0, 0, 0, 0.76) 85%, transparent 100%);
}

#chat .mes[is_user="true"] .mesAvatarWrapper :is(.mesIDDisplay, .mes_timer, .tokenCounterDisplay) {
    grid-row: 2;
    font-size: 0.7em;
}

#chat .mes[is_user="true"] .mesAvatarWrapper .mesIDDisplay { grid-column: 2; }
#chat .mes[is_user="true"] .mesAvatarWrapper .mes_timer { grid-column: 3; }
#chat .mes[is_user="true"] .mesAvatarWrapper .tokenCounterDisplay { grid-column: 4; }

/* v5.33 消息卷尾款识：保留真实编号、计时和 Token，只清除官方 0.7 灰态。 */
#chat .mes .mesAvatarWrapper :is(.mesIDDisplay, .mes_timer, .tokenCounterDisplay) {
    display: inline-flex;
    min-block-size: 1.22rem;
    align-items: center;
    gap: 0.16rem;
    padding: 0.02rem 0.2rem 0.08rem;
    color: var(--ysd-ink-soft);
    border: 0;
    border-block-end: 1px solid var(--ysd-hairline);
    border-radius: 0;
    background: transparent;
    font-family: var(--ysd-font-body);
    font-weight: 400;
    line-height: 1.1;
    letter-spacing: 0.04em;
    opacity: 1;
    filter: none;
    box-shadow: none;
    text-shadow: none;
}

#chat .mes[is_user="false"][is_system="false"] .mesAvatarWrapper
    :is(.mesIDDisplay, .mes_timer, .tokenCounterDisplay) {
    font-size: 0.92em;
}

#chat .mes .mesAvatarWrapper .mesIDDisplay { color: var(--ysd-cinnabar-dark); }
#chat .mes .mesAvatarWrapper .mes_timer { color: var(--ysd-mist-blue); }
#chat .mes .mesAvatarWrapper .tokenCounterDisplay { color: var(--ysd-jade); }

#chat .mes .mesAvatarWrapper :is(.mesIDDisplay, .mes_timer, .tokenCounterDisplay)::before {
    content: var(--ysd-icon-image-content);
    display: var(--ysd-semantic-icon-display);
    inline-size: 0.86rem;
    block-size: 0.86rem;
    flex: 0 0 0.86rem;
    color: transparent;
    border: 0;
    background-color: transparent;
    background-image: var(--ysd-selection-motifs);
    background-repeat: no-repeat;
    background-size: var(--ysd-selection-background-size);
