/* ===== src/windows/controls.css ===== */
/* 真实表单控件：保留官方 ::before 状态链，但把西式方框/勾替换为花月水墨印记。 */
:where(#sheld, .drawer-content, .popup, .modal, #options, #completion_prompt_manager_popup)
    input:is([type="checkbox"], [type="radio"]) {
    appearance: none;
    -webkit-appearance: none;
    position: relative;
    inline-size: 1.58rem;
    block-size: 1.58rem;
    min-inline-size: 1.58rem;
    margin: 0.12rem 0.34rem;
    border: 0 !important;
    border-radius: 0 !important;
    background-color: var(--ysd-control-transparent) !important;
    background-image: var(--ysd-range-host-background-image) !important;
    box-shadow: none !important;
    outline: none;
    opacity: 1 !important;
    filter: none !important;
    vertical-align: middle;
    cursor: pointer;
}

:where(#sheld, .drawer-content, .popup, .modal, #options, #completion_prompt_manager_popup)
    input[type="checkbox"]::before {
    content: "";
    display: block;
    inline-size: 1.42rem;
    block-size: 1.42rem;
    width: 1.42rem;
    height: 1.42rem;
    margin: auto;
    background-color: var(--ysd-control-transparent);
    background-image: var(--ysd-selection-motifs);
    background-repeat: no-repeat;
    background-size: var(--ysd-selection-background-size);
    background-position: var(--ysd-selection-off-position);
    clip-path: var(--ysd-selection-clip);
    transform: scale(0.72);
    transform-origin: center;
    opacity: 1;
    visibility: visible;
    filter: none;
    pointer-events: none;
}

:where(#sheld, .drawer-content, .popup, .modal, #options, #completion_prompt_manager_popup)
    input[type="checkbox"]:checked {
    background-color: var(--ysd-control-transparent) !important;
    outline: none;
}

:where(#sheld, .drawer-content, .popup, .modal, #options, #completion_prompt_manager_popup)
    input[type="checkbox"]:checked::before {
    background-position: var(--ysd-selection-on-position);
    transform: scale(0.94);
    opacity: 1;
    visibility: visible;
    filter: none;
}

:where(#sheld, .drawer-content, .popup, .modal, #options, #completion_prompt_manager_popup)
    input[type="radio"] {
    background-image: var(--ysd-selection-motifs) !important;
    background-repeat: no-repeat !important;
    background-size: var(--ysd-selection-background-size) !important;
    background-position: var(--ysd-radio-off-position) !important;
    opacity: 1 !important;
}

:where(#sheld, .drawer-content, .popup, .modal, #options, #completion_prompt_manager_popup)
    input[type="radio"]:checked {
    background-position: var(--ysd-radio-on-position) !important;
    background-color: var(--ysd-control-transparent) !important;
    outline: none;
    opacity: 1 !important;
}

:where(#sheld, .drawer-content, .popup, .modal, #options, #completion_prompt_manager_popup)
    input:is([type="checkbox"], [type="radio"]):disabled {
    background-color: var(--ysd-control-transparent) !important;
    opacity: var(--ysd-control-disabled-opacity) !important;
    cursor: not-allowed;
}

:where(#sheld, .drawer-content, .popup, .modal, #options, #completion_prompt_manager_popup)
    input:is([type="checkbox"], [type="radio"]):focus-visible {
    outline: 1px solid var(--ysd-jade);
    outline-offset: 1px;
    box-shadow: none !important;
}

/* 原生滑杆：清除官方黑色内阴影、亮度滤镜和白色圆头，保留真实 range 交互。 */
.drawer-content input[type="range"],
.drawer-content .neo-range-slider {
    -webkit-appearance: none !important;
    appearance: none !important;
    height: var(--ysd-range-track-height) !important;
    border: 0 !important;
    border-radius: 0 !important;
    background-color: var(--ysd-control-transparent) !important;
    background-image: var(--ysd-range-host-background-image) !important;
    box-shadow: none !important;
    filter: none !important;
    opacity: 1 !important;
}

.drawer-content input[type="range"]:disabled,
.drawer-content .neo-range-slider:disabled {
    background-image: none !important;
    filter: none !important;
    opacity: 1 !important;
}

.drawer-content input[type="range"]::-webkit-slider-runnable-track {
    height: var(--ysd-range-track-height);
    border: 0;
    background-color: var(--ysd-control-transparent);
    background-image: var(--ysd-range-track);
    background-repeat: no-repeat;
    background-position: var(--ysd-range-track-position);
    background-size: var(--ysd-range-track-size);
    opacity: var(--ysd-range-track-opacity);
    box-shadow: none;
    filter: none;
}

.drawer-content input[type="range"]:disabled::-webkit-slider-runnable-track {
    background-image: var(--ysd-range-track-disabled);
    opacity: var(--ysd-range-track-disabled-opacity);
}

.drawer-content input[type="range"]::-webkit-slider-thumb {
    -webkit-appearance: none !important;
    appearance: none !important;
    width: var(--ysd-range-thumb-size);
    height: var(--ysd-range-thumb-size);
    margin-top: calc((var(--ysd-range-track-height) - var(--ysd-range-thumb-size)) / 2);
    border: 0 !important;
    border-radius: 0 !important;
    background-color: var(--ysd-control-transparent) !important;
    background-image: var(--ysd-selection-motifs) !important;
    background-repeat: no-repeat !important;
    background-size: var(--ysd-selection-background-size) !important;
    background-position: var(--ysd-radio-on-position) !important;
    box-shadow: none !important;
    filter: none !important;
    opacity: 1 !important;
}

.drawer-content input[type="range"]:is(:hover, :focus-visible)::-webkit-slider-thumb {
    background-position: var(--ysd-selection-on-position) !important;
    transform: scale(1.08);
}

.drawer-content input[type="range"]:focus-visible::-webkit-slider-thumb {
    outline: 2px solid var(--theme-focus-ring);
    outline-offset: 1px;
}

.drawer-content input[type="range"]:disabled::-webkit-slider-thumb {
    background-position: var(--ysd-selection-off-position) !important;
    transform: none;
    opacity: var(--ysd-control-disabled-opacity) !important;
}

.drawer-content input[type="range"]::-moz-range-track {
    height: var(--ysd-range-track-height);
    border: 0;
    background-color: var(--ysd-control-transparent);
    background-image: var(--ysd-range-track);
    background-repeat: no-repeat;
    background-position: var(--ysd-range-track-position);
    background-size: var(--ysd-range-track-size);
    opacity: var(--ysd-range-track-opacity);
    box-shadow: none;
    filter: none;
}

.drawer-content input[type="range"]:disabled::-moz-range-track {
    background-image: var(--ysd-range-track-disabled);
    opacity: var(--ysd-range-track-disabled-opacity);
}

.drawer-content input[type="range"]::-moz-range-thumb {
    width: var(--ysd-range-thumb-size);
    height: var(--ysd-range-thumb-size);
    border: 0 !important;
    border-radius: 0 !important;
    background-color: var(--ysd-control-transparent) !important;
    background-image: var(--ysd-selection-motifs) !important;
    background-repeat: no-repeat !important;
    background-size: var(--ysd-selection-background-size) !important;
    background-position: var(--ysd-radio-on-position) !important;
    box-shadow: none !important;
    filter: none !important;
    opacity: 1 !important;
}

.drawer-content input[type="range"]:is(:hover, :focus-visible)::-moz-range-thumb {
    background-position: var(--ysd-selection-on-position) !important;
    transform: scale(1.08);
}

.drawer-content input[type="range"]:focus-visible::-moz-range-thumb {
    outline: 2px solid var(--theme-focus-ring);
    outline-offset: 1px;
}

.drawer-content input[type="range"]:disabled::-moz-range-thumb {
    background-position: var(--ysd-selection-off-position) !important;
    transform: none;
    opacity: var(--ysd-control-disabled-opacity) !important;
}

