/* 官方瞬时反馈：保留 flashHighlight 与拖放类链，只改掉黑灰内阴影、透明闪灭、虚线框和缩放脉冲。 */
@keyframes ysd-watermark-flash {
    0%, 100% {
        opacity: 1;
        background-color: var(--ysd-paper-control);
    }

    50% {
        opacity: 1;
        background-color: var(--ysd-jade-soft);
    }
}

@keyframes ysd-watermark-pulse {
    from {
        opacity: 1;
        background-color: var(--ysd-paper-control);
        filter: none;
    }

    to {
        opacity: 1;
        background-color: var(--ysd-jade-soft);
        filter: none;
    }
}

.flash.animated {
    animation-name: ysd-watermark-flash !important;
    box-shadow: none !important;
