/* ===== src/windows/prompt-manager.css ===== */
/* 对话补全预设：正常/禁用/选中/悬停/焦点/展开/闭合。 */
#completion_prompt_manager {
    color: var(--ysd-ink);
    text-shadow: none;
}

#completion_prompt_manager #completion_prompt_manager_list {
    border: 0;
    background: transparent;
}

#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt {
    color: var(--ysd-ink);
    position: relative;
    margin-bottom: 0.72em;
    padding: 0.52em 0.34em 0.82em;
    border: 0;
    border-radius: 0;
    background: transparent;
    box-shadow: none;
    text-shadow: none;
    opacity: 1;
    filter: none;
    transition: color var(--ysd-speed), background-color var(--ysd-speed);
}

#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt::after {
    content: "";
    position: absolute;
    inset-inline: 0;
    bottom: -0.2em;
    block-size: 0.9em;
    background-image: var(--ysd-branch-dividers);
    background-repeat: no-repeat;
    background-size: 100% 200%;
    background-position: var(--ysd-selection-on-position);
    pointer-events: none;
    opacity: var(--ysd-branch-opacity);
}

#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt:nth-child(even)::after {
    background-position: 0 100%;
}

#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt:hover {
    background: var(--ysd-prompt-hover-surface);
}

#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt:focus-within {
    background: var(--ysd-prompt-focus-surface);
