    background-repeat: no-repeat;
    background-size: var(--ysd-selection-background-size);
    background-position: var(--ysd-selection-off-position);
    color: transparent;
    font-size: 0;
    line-height: 1;
    pointer-events: none;
}

#completion_prompt_manager #completion_prompt_manager_list .prompt-manager-toggle-action.fa-toggle-on::before {
    background-position: var(--ysd-selection-on-position);
}

#completion_prompt_manager #completion_prompt_manager_list .prompt-manager-toggle-action.fa-toggle-off::before {
    background-position: var(--ysd-selection-off-position);
}

