/* 弹层确认/取消保留文字并增加花印；关闭键直接替换圆叉。 */
:where(.popup .popup-button-ok, #dialogue_popup_ok, #character_popup_ok)::before,
:where(.popup .popup-button-cancel, #dialogue_popup_cancel)::before,
.popup .popup-button-close::before {
    content: var(--ysd-icon-image-content) !important;
    display: inline-block;
    inline-size: var(--ysd-semantic-icon-size);
    block-size: var(--ysd-semantic-icon-size);
    margin-inline-end: 0.24em;
    background-color: var(--ysd-control-transparent);
    background-image: var(--ysd-selection-motifs);
    background-repeat: no-repeat;
    background-size: var(--ysd-selection-background-size);
    color: transparent !important;
    font-size: 0;
    line-height: 1;
    vertical-align: var(--ysd-semantic-icon-align);
    opacity: 1;
    filter: none;
    box-shadow: none;
    text-shadow: none;
    pointer-events: none;
}

:where(.popup .popup-button-ok, #dialogue_popup_ok, #character_popup_ok)::before {
    background-position: var(--ysd-selection-on-position);
}

:where(.popup .popup-button-cancel, #dialogue_popup_cancel)::before,
.popup .popup-button-close::before {
    background-position: var(--ysd-selection-off-position);
}

.popup .popup-button-close::before {
    margin-inline-end: 0;
}

/* MovingUI 拖动把手：仅替换原生 grip 生成层，display/cursor/拖动事件仍由官方控制。 */
