    inline-size: var(--ysd-window-action-size);
    block-size: var(--ysd-window-action-size);
    background-color: var(--ysd-control-transparent);
    background-image: var(--ysd-ui-sprite);
    background-repeat: no-repeat;
    background-size: 400% 400%;
    background-position: var(--ysd-ui-bamboo-position);
    color: transparent !important;
    font-size: 0;
    line-height: 1;
    opacity: 1;
    filter: none;
    box-shadow: none;
    text-shadow: none;
    pointer-events: none;
