    background-color: var(--ysd-control-transparent);
    background-image: var(--ysd-ui-sprite);
    background-repeat: no-repeat;
    background-size: 400% 400%;
    background-position: var(--ysd-action-delete-position);
    color: transparent !important;
    font-size: 0;
    line-height: 1;
    opacity: 1;
    filter: none;
    box-shadow: none;
    text-shadow: none;
    pointer-events: none;
    transition: transform var(--ysd-speed);
}

:where(.zoomed_avatar, .draggable) .dragClose:is(:hover, :focus-visible)::before {
    transform: translateY(-1px) scale(1.08);
}

/* ===== src/windows/popups.css ===== */
/* 临时界面：Toast、确认框、弹窗、加载与通知。 */
:where(.popup, .modal, .dialogue_popup, .ui-dialog, .drawer-content[data-dragged]) {
    color: var(--ysd-ink);
    border-color: var(--ysd-hairline);
    border-radius: 0;
    background: var(--ysd-paper-page);
    box-shadow: none;
    text-shadow: none;
    filter: none;
}

/* 新旧弹层真实外壳统一为暖纸卷页，不改尺寸、开合、滚动或焦点。 */
