    border: 0;
    background-color: transparent;
    background-image: none;
    box-shadow: none;
    text-shadow: none;
    filter: none;
    opacity: 1;
}

/* 标题以桃柳长枝收尾，替代矩形标题栏。 */
:where(
    .popup .popup-header,
    #dialogue_popup_text > h3:first-child,
    #bulk_tag_popup h3:first-child,
    #select_chat_popup h3:first-child
