    color: var(--ysd-cinnabar-dark);
    padding-block-end: 0.78rem;
    border: 0;
    border-radius: 0;
    background-color: transparent;
    background-image: var(--ysd-branch-dividers);
    background-repeat: no-repeat;
    background-position: bottom center;
    background-size: 100% 0.72rem;
    box-shadow: none;
    text-shadow: none;
    filter: none;
    opacity: 1;
}

/* 将官方模糊强度归零并改成暖墨薄纱，保留遮罩本身及关闭逻辑。 */
.popup[open],
:where(#shadow_popup, #shadow_select_chat_popup, #bulk_tag_shadow_popup) {
    --SmartThemeBlurStrength: var(--ysd-popup-blur);
}

.popup[open]::backdrop,
:where(#shadow_popup, #shadow_select_chat_popup, #bulk_tag_shadow_popup) {
    background-color: var(--ysd-paper-veil);
}

.popup .popup-inputs {
    color: var(--ysd-ink-soft);
    opacity: 1;
    filter: none;
    text-shadow: none;
}

:where(.popup .popup-controls, #dialogue_popup_controls) {
    padding-block-start: 0.72rem;
    border: 0;
    background-color: transparent;
    background-image: var(--ysd-branch-dividers);
    background-repeat: no-repeat;
    background-position: top center;
    background-size: 100% 0.62rem;
    box-shadow: none;
}

:where(.popup .popup-controls, #dialogue_popup_controls) .menu_button {
    color: var(--ysd-ink);
    border: 0;
    border-radius: 0;
    background-color: var(--ysd-paper-control);
    box-shadow: none;
    text-shadow: none;
    filter: none;
    opacity: 1;
}

:where(.popup .popup-controls, #dialogue_popup_controls) .menu_button:is(:hover, :focus-visible) {
    color: var(--ysd-jade);
    border: 0;
    background-color: var(--ysd-jade-soft);
    box-shadow: none;
    filter: none;
}

:where(.popup .popup-button-ok, #dialogue_popup_ok) {
    color: var(--ysd-cinnabar-dark);
    border-block-end: 2px solid var(--ysd-cinnabar);
    background-color: var(--ysd-paper-control);
    box-shadow: none;
    filter: none;
}

:where(.popup .popup-button-cancel, #dialogue_popup_cancel) {
    color: var(--ysd-ink-soft);
    background-color: var(--ysd-paper-control);
}

.popup .popup-button-close {
    border: 0;
    border-radius: 0;
    background-color: transparent;
    box-shadow: none;
    filter: none;
    opacity: 1;
}

#toast-container > .toast {
