#qr--popout > .qr--header > .qr--controls > .qr--close::before {
    content: var(--ysd-close-label);
    display: block;
    width: 1.42rem;
    height: 1.42rem;
    color: var(--ysd-cinnabar-dark);
    font-family: var(--ysd-font-display);
    font-size: 0.88rem;
    line-height: 1.42rem;
    text-align: center;
    background-color: transparent;
    background-image: none;
    text-shadow: none;
    filter: none;
    opacity: 1;
    pointer-events: none;
}

#qr--popout > .qr--header > .qr--controls > .qr--close:focus-visible {
    outline: 2px solid var(--ysd-focus-ring);
    outline-offset: 2px;
}

.ctx-menu > .list-group .ctx-header {
    color: var(--ysd-cinnabar-dark);
    font-family: var(--ysd-font-display);
    font-weight: 400;
}

/* STscript/斜杠补全：覆盖官方 theme 模式中混入的灰色 color-mix。 */
:where(.autoComplete, .autoComplete-details) {
    --ac-color-border: var(--ysd-hairline);
    --ac-color-background: var(--ysd-paper-page);
    --ac-color-text: var(--ysd-ink);
    --ac-color-matchedBackground: transparent;
    --ac-color-matchedText: var(--ysd-cinnabar-dark);
    --ac-color-selectedBackground: var(--ysd-jade-soft);
    --ac-color-selectedText: var(--ysd-ink);
    --ac-color-notSelectableBackground: var(--ysd-paper-disabled);
    --ac-color-notSelectableText: var(--ysd-ink-muted);
    --ac-color-hoveredBackground: var(--ysd-paper-hover);
    --ac-color-hoveredText: var(--ysd-ink);
    --ac-color-argName: var(--ysd-mist-blue);
    --ac-color-type: var(--ysd-jade);
    --ac-color-cmd: var(--ysd-bronze);
    --ac-color-symbol: var(--ysd-mist-blue);
    --ac-color-string: var(--ysd-cinnabar-dark);
    --ac-color-number: var(--ysd-success);
    --ac-color-variable: var(--ysd-mist-blue);
    --ac-color-variableLanguage: var(--ysd-jade);
    --ac-color-punctuation: var(--ysd-bronze);
    --ac-color-punctuationL1: var(--ysd-cinnabar);
    --ac-color-punctuationL2: var(--ysd-jade);
    --ac-color-currentParenthesis: var(--ysd-cinnabar);
    --ac-color-comment: var(--ysd-ink-muted);
    --ac-color-keyword: var(--ysd-cinnabar-dark);
}

.autoComplete > .item > * {
    color: var(--ysd-ink);
    border: 0;
    background-color: transparent;
    background-image: var(--ysd-branch-dividers);
    background-repeat: no-repeat;
    background-position: bottom center;
    background-size: 100% 0.34rem;
    box-shadow: none;
    text-shadow: none;
    filter: none;
    opacity: 1;
}

.autoComplete > .item:hover > * {
    color: var(--ysd-ink);
    background-color: var(--ysd-paper-hover);
}

.autoComplete > .item.selected > * {
    color: var(--ysd-ink);
    background-color: var(--ysd-jade-soft);
}

.autoComplete > .item.selected.not-selectable > * {
    color: var(--ysd-ink-muted);
    background-color: var(--ysd-paper-disabled);
}

.autoComplete-details > .specs {
    border-block-end-color: var(--ysd-hairline);
    background-image: var(--ysd-branch-dividers);
    background-repeat: no-repeat;
    background-position: bottom center;
    background-size: 100% 0.42rem;
}

body > .ui-autocomplete.ui-menu .ui-menu-item:last-child .ui-menu-item-wrapper,
:where(#options .options-content, #extensionsMenu, #character_context_menu ul) > :last-child {
    background-image: none;
}

/* ===== src/windows/mobile.css ===== */
/* 手机独立母版：浅横幅上图、下题签；覆盖 360/390/430px。 */
@media (max-width: 1000px) {
    #top-settings-holder {
        justify-content: flex-start;
        overflow-x: auto;
        overflow-y: hidden;
    }

    :where(
        #ai-config-button,
        #sys-settings-button,
        #advanced-formatting-button,
        #WI-SP-button,
        #user-settings-button,
        #backgrounds-button,
        #extensions-settings-button,
        #persona-management-button,
        #rightNavHolder
    ) .drawer-icon {
        width: 2.48rem;
        min-width: 2.48rem;
        height: 2.48rem;
    }

    :where(
        #ai-config-button,
        #sys-settings-button,
        #advanced-formatting-button,
        #WI-SP-button,
        #user-settings-button,
        #backgrounds-button,
        #extensions-settings-button,
        #persona-management-button,
        #rightNavHolder
    ) .drawer-icon.closedIcon {
        opacity: 0.92;
    }

    #sheld {
        border-radius: 0;
    }

    #chat .mes {
        padding-inline: clamp(0.72rem, 3.6vw, 1.35rem);
    }

    #chat .mes[is_user="true"] {
        grid-template-columns: minmax(0, 1fr);
        grid-template-rows: auto auto;
        row-gap: 0.7rem;
        min-height: 0;
        align-items: start;
    }

    #chat .mes[is_user="true"] .mesAvatarWrapper {
        grid-column: 1;
        grid-row: 1;
    }

    #chat .mes[is_user="true"] .mesAvatarWrapper .avatar {
        height: clamp(5.8rem, 23vw, 7.2rem);
    }

    #chat .mes[is_user="true"] .mesAvatarWrapper .avatar img {
        width: 100%;
        object-fit: cover;
        object-position: 50% 36%;
        image-rendering: auto;
        filter: none;
        -webkit-mask-image: linear-gradient(90deg, transparent 0%, rgba(0, 0, 0, 0.72) 12%, #000 29%, #000 71%, rgba(0, 0, 0, 0.72) 88%, transparent 100%);
        mask-image: linear-gradient(90deg, transparent 0%, rgba(0, 0, 0, 0.72) 12%, #000 29%, #000 71%, rgba(0, 0, 0, 0.72) 88%, transparent 100%);
    }

    #chat .mes[is_user="true"] .mes_block {
        grid-column: 1;
        grid-row: 2;
        inline-size: 100%;
        min-inline-size: 0;
        padding: 0.25rem 0.2rem 0.1rem;
    }

    #chat .mes[is_user="false"][is_system="false"] > .mes_block {
        inline-size: 100%;
        min-inline-size: 0;
    }

    #chat .mes[is_system="false"] > .mes_block > .mes_text {
        inline-size: min(100%, 68em);
        max-inline-size: 100%;
        margin-inline: auto !important;
        padding-inline: clamp(0.15rem, 1.4vw, 0.5rem) !important;
        box-sizing: border-box;
    }

    #chat .mes[is_user="false"][is_system="false"] .name_text {
        font-size: 1.55em;
    }

    #chat .mes_text {
        line-height: 1.78;
        letter-spacing: 0.02em;
    }

    #chat .mes_text blockquote {
        padding-left: 1.65em;
    }

    #form_sheld {
        padding-inline: 0.25rem;
    }

    #send_form #nonQRFormItems {
        flex-wrap: nowrap;
    }

    #leftSendForm,
    #rightSendForm {
        flex-wrap: nowrap;
        min-width: 0;
    }

    #send_form :is(
        #options_button,
        #extensionsMenuButton,
        #mes_continue,
        #mes_impersonate,
        #send_but,
        #mes_stop,
        #stscript_continue,
        #stscript_pause,
        #stscript_stop
    ) {
        width: 2.2rem;
        min-width: 2.2rem;
        height: 2.2rem;
    }

    #send_textarea {
        min-width: 0;
        padding-inline: 0.55rem;
        font-size: 0.88em;
    }

    #qr--bar > .qr--buttons .qr--button {
        padding-inline: 0.62rem 0.5rem;
    }

    :where(
        #left-nav-panel,
        #rm_api_block,
        #AdvancedFormatting,
        #WorldInfo,
        #user-settings-block,
        #Backgrounds,
        #rm_extensions_block,
        #PersonaManagement,
        #right-nav-panel
    ) {
        max-width: 100dvw;
        border-radius: 0;
        overflow-y: auto;
    }

    #PersonaManagement .persona_management_left_column,
    #PersonaManagement .persona_management_right_column {
        width: 100%;
        min-width: 0;
    }

    #user-settings-block #user-settings-block-content {
        flex-direction: column;
        align-items: stretch;
    }

    /*
     * 插件页原生是可换行的横向 flex，并给两列同时挂了 flex1 + wide50p。
     * 手机端必须把整条祖先链改成单列且禁止再次换列，否则内容会排到视口右侧，
     * 再被官方 scrollableInner 的 overflow-x:hidden 截掉。
     */
    #rm_extensions_block > .extensions_block {
        width: 100%;
        min-width: 0;
        max-width: 100%;
        flex-flow: column nowrap;
        align-items: stretch;
        overflow-x: hidden;
    }

    #rm_extensions_block :is(#extensions_settings, #extensions_settings2) {
        flex: 0 0 auto;
        width: 100% !important;
        min-width: 0 !important;
        max-width: 100%;
    }

    #rm_extensions_block > .extensions_block > :is(.wide100p, hr) {
        flex: 0 0 auto;
        width: 100%;
        min-width: 0;
        max-width: 100%;
    }

    #rm_extensions_block :is(
        #extensions_settings,
        #extensions_settings2
    ) :is(
        .extension_container,
        .extension_block,
        .inline-drawer,
        .inline-drawer-content,
        .extensions_toolbar,
        .extensions_url_block
    ) {
        min-width: 0;
        max-width: 100%;
        box-sizing: border-box;
    }

    #rm_extensions_block :is(
        .extensions_toolbar,
        .extensions_url_block,
        .extensions_info .extension_block,
        .extensions_info .extension_actions
    ) {
        flex-wrap: wrap;
    }

    #rm_extensions_block .extensions_info .extension_text_block {
        min-width: 0;
        white-space: normal;
        overflow: visible;
        overflow-wrap: anywhere;
        text-overflow: clip;
    }

    #rm_extensions_block :is(input, select, textarea, .text_pole) {
        min-width: 0;
        max-width: 100%;
        box-sizing: border-box;
    }

    /*
     * 回复格式页的四个真实内容列共用一个可换行横向 flex；官方手机规则漏了
     * #SystemPromptColumn。统一释放列宽，避免系统提示词列在窄屏保留桌面收缩宽度。
     */
    #AdvancedFormatting :is(
        #ContextSettings,
        #InstructSettingsColumn,
        #InstructSequencesColumn,
        #SystemPromptColumn
    ) {
        flex: 0 0 100%;
        width: 100%;
        min-width: 0;
        max-width: 100%;
        box-sizing: border-box;
    }

    #AdvancedFormatting :is(
        #ContextSettings,
        #InstructSettingsColumn,
        #InstructSequencesColumn,
        #SystemPromptColumn
    ) :is(input, select, textarea, .text_pole, details) {
        min-width: 0;
        max-width: 100%;
        box-sizing: border-box;
    }

    #WorldInfo #WIMultiSelector,
    #WorldInfo #WIMultiSelector .select2-container,
    #WorldInfo #world_editor_select,
    #WorldInfo #world_editor_select ~ .select2-container {
        width: 100% !important;
        min-width: 0;
    }

    /* 世界书激活设置：官方标签挂 whitespacenowrap，窄屏时必须释放文字容量。 */
    #WorldInfo #wiActivationSettings,
    #WorldInfo #wiCheckboxes,
    #WorldInfo #wiCheckboxes > .checkbox_label {
        width: 100%;
        min-width: 0;
        max-width: 100%;
        box-sizing: border-box;
    }

    #WorldInfo #wiCheckboxes > .checkbox_label > small.whitespacenowrap {
        min-width: 0;
        white-space: normal;
        overflow-wrap: anywhere;
    }

    /*
     * 群组编辑区原生把策略、四个字段、七个动作和复选项塞在同一横排，
     * textarea 还带 200px 最小宽度。手机端按真实区域分段纵排，不改桌面。
     */
    #right-nav-panel #rm_group_chats_block,
    #right-nav-panel #group-metadata-controls,
    #right-nav-panel #rm_group_top_bar,
    #right-nav-panel #rm_group_buttons,
    #right-nav-panel #GroupFavDelOkBack {
        width: 100%;
        min-width: 0;
        max-width: 100%;
        box-sizing: border-box;
    }

    #right-nav-panel #rm_group_top_bar {
        flex-flow: column nowrap;
        align-items: stretch;
    }

    #right-nav-panel #rm_group_buttons {
        flex: 0 0 auto;
        flex-flow: column nowrap;
        padding-inline: 0;
    }

    #right-nav-panel #rm_group_buttons > .flex1 {
        flex: 0 0 auto;
        width: 100%;
        min-width: 0;
        max-width: 100%;
    }

    #right-nav-panel #rm_group_buttons :is(label, label.whitespacenowrap) {
        min-width: 0;
        white-space: normal;
        overflow-wrap: anywhere;
    }

    #right-nav-panel #rm_group_buttons textarea {
        width: 100%;
        min-width: 0;
        max-width: 100%;
        box-sizing: border-box;
    }

    #right-nav-panel #GroupFavDelOkBack {
        flex: 0 0 auto;
        flex-wrap: wrap;
        justify-content: flex-start;
    }

    #right-nav-panel #GroupFavDelOkBack > .flex1 {
        flex: 1 0 100%;
        width: 100%;
        min-width: 0;
    }

    #right-nav-panel #GroupFavDelOkBack .checkbox_label.whitespacenowrap {
        min-width: 0;
        white-space: normal;
        overflow-wrap: anywhere;
    }

    :where(.popup, .modal, .dialogue_popup, .ui-dialog) {
        max-width: calc(100dvw - 1rem);
        max-height: calc(100dvh - 1rem);
    }

    :where(
        #left-nav-panel,
        #rm_api_block,
        #AdvancedFormatting,
        #WorldInfo,
        #user-settings-block,
        #Backgrounds,
        #rm_extensions_block,
        #PersonaManagement,
        #right-nav-panel
    ) :is(.menu_button, button, select, input:not([type="checkbox"]):not([type="radio"]):not([type="range"])) {
        min-height: 2.35rem;
    }
}

@media (max-width: 430px) {
    #chat .mes[is_user="true"] .name_text {
        font-size: 1.35em;
    }

    #chat .mes[is_user="false"][is_system="false"] {
        padding-block: 1.45rem 2rem;
    }

    #chat .mes_buttons {
        gap: 0.15rem;
    }
}

@media (max-width: 390px) {
    :where(
        #ai-config-button,
        #sys-settings-button,
        #advanced-formatting-button,
        #WI-SP-button,
        #user-settings-button,
        #backgrounds-button,
        #extensions-settings-button,
        #persona-management-button,
        #rightNavHolder
    ) .drawer-icon {
        width: 2.34rem;
        min-width: 2.34rem;
        height: 2.34rem;
    }

    #chat .mes[is_user="true"] .mesAvatarWrapper :is(.mesIDDisplay, .mes_timer, .tokenCounterDisplay) {
        font-size: 0.66em;
    }

    #send_form :is(#options_button, #extensionsMenuButton, #mes_continue, #mes_impersonate, #send_but, #mes_stop) {
        width: 2.08rem;
        min-width: 2.08rem;
        height: 2.08rem;
    }
}

@media (max-width: 360px) {
    #chat .mes {
        padding-inline: 0.65rem;
    }

    #send_form :is(#options_button, #extensionsMenuButton, #mes_continue, #mes_impersonate, #send_but, #mes_stop) {
        width: 1.95rem;
        min-width: 1.95rem;
        height: 1.95rem;
    }

    #send_textarea {
        font-size: 0.86em;
    }
}

/* v7 阅读轴合同：700px 内显式释放消息侧槽并保持对称正文轴。 */
@media (max-width: 700px) {
    #chat .mes[is_system="false"] {
        flex-direction: column;
    }

    #chat .mes[is_system="false"] > .mes_block {
        inline-size: 100%;
        min-inline-size: 0;
    }

    #chat .mes[is_system="false"] > .mes_block > .mes_text {
        margin-inline: auto !important;
        padding-inline: clamp(0.15rem, 1.4vw, 0.5rem) !important;
        box-sizing: border-box;
    }
}

@media (prefers-reduced-motion: reduce) {
    :where(
        #ai-config-button,
        #sys-settings-button,
        #advanced-formatting-button,
        #WI-SP-button,
        #user-settings-button,
        #backgrounds-button,
        #extensions-settings-button,
        #persona-management-button,
        #rightNavHolder
    ) .drawer-icon,
    #send_form :is(#options_button, #extensionsMenuButton, #mes_continue, #mes_impersonate, #send_but, #mes_stop),
    #chat .mes .mes_button {
        transition: none;
    }
}

/* ===== src/fallback.css ===== */
/* 远程字体/图片失败回退：保留真实宿主、标题、焦点、状态和点击能力。 */
:root {
    --ysd-font-body: "Zhuque Fangsong", "Songti SC", "Noto Serif CJK SC", "SimSun", serif;
    --ysd-font-display: "Ma Shan Zheng", "STKaiti", "KaiTi", cursive;
}

:where(
    #ai-config-button,
    #sys-settings-button,
    #advanced-formatting-button,
    #WI-SP-button,
    #user-settings-button,
    #backgrounds-button,
    #extensions-settings-button,
    #persona-management-button,
    #rightNavHolder
) .drawer-icon,
#send_form :is(#options_button, #extensionsMenuButton, #mes_continue, #mes_impersonate, #send_but, #mes_stop) {
    font-size: 1em;
    opacity: 1;
}

:where(
    #ai-config-button,
    #sys-settings-button,
    #advanced-formatting-button,
    #WI-SP-button,
    #user-settings-button,
    #backgrounds-button,
    #extensions-settings-button,
    #persona-management-button,
    #rightNavHolder
) .drawer-icon::before,
#send_form :is(#options_button, #extensionsMenuButton, #mes_continue, #mes_impersonate, #send_but, #mes_stop)::before {
    color: transparent;
}

#chat .mes[is_user="true"] .mesAvatarWrapper .avatar:has(img[style*="display: none"]),
#chat .mes[is_user="true"] .mesAvatarWrapper .avatar:has(.missing-avatar) {
    min-height: 5.8rem;
    background:
        linear-gradient(90deg, transparent, rgba(63, 104, 88, 0.16), transparent),
        var(--ysd-paper-page);
}
